"""Additivity of the Iwasawa invariants (mu, lambda) under multiplication."""
from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List

Poly = List[int]

def content(f: Poly) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def prim_part(f: Poly) -> Poly:
    c = content(f)
    return [a // c for a in f]

def padic_val(p: int, n: int) -> int:
    n, v = abs(n), 0
    while n % p == 0:
        n //= p; v += 1
    return v

def mu_inv(p: int, f: Poly) -> int:
    return padic_val(p, content(f))

def lambda_inv(p: int, f: Poly) -> int:
    r = [c % p for c in prim_part(f)]
    return next(i for i, c in enumerate(r) if c != 0)

def poly_mul(f: Poly, g: Poly) -> Poly:
    out = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            out[i + j] += a * b
    return out

if __name__ == "__main__":
    p, f, g = 3, [3, 0, 6], [0, 9, 9]
    fg = poly_mul(f, g)
    print("mu(fg) =", mu_inv(p, fg), "= mu(f)+mu(g) =", mu_inv(p, f) + mu_inv(p, g))
    print("lam(fg)=", lambda_inv(p, fg), "= lam(f)+lam(g)=", lambda_inv(p, f) + lambda_inv(p, g))
    assert mu_inv(p, fg) == mu_inv(p, f) + mu_inv(p, g)
    assert lambda_inv(p, fg) == lambda_inv(p, f) + lambda_inv(p, g)
    print("additivity verified")

"""lambda(f) equals the order of vanishing at 0 of the reduced primitive part."""
from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List

Poly = List[int]

def content(f: Poly) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def reduced_prim(p: int, f: Poly) -> Poly:
    c = content(f)
    return [(a // c) % p for a in f]

def lambda_inv(p: int, f: Poly) -> int:
    r = reduced_prim(p, f)
    return next(i for i, c in enumerate(r) if c != 0)

def root_mult_at_zero(p: int, f: Poly) -> int:
    r = reduced_prim(p, f)
    m = 0
    while m < len(r) and r[m] == 0:
        m += 1
    return m

if __name__ == "__main__":
    p = 7
    for f in [[7, 0, 0, 3], [0, 0, 14, 7, 2], [1, 7, 49]]:
        assert lambda_inv(p, f) == root_mult_at_zero(p, f)
        print(f"f={f}: lambda = rootMult_0 =", lambda_inv(p, f))
    print("lambda = order of vanishing verified")

"""The iterated Matsuno twist formula for the lambda-invariant."""
from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List, Tuple

Poly = List[int]

def content(f: Poly) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def mu_inv(p: int, f: Poly) -> int:
    n, v = content(f), 0
    while n % p == 0:
        n //= p; v += 1
    return v

def lambda_inv(p: int, f: Poly) -> int:
    c = content(f)
    r = [(a // c) % p for a in f]
    return next(i for i, x in enumerate(r) if x != 0)

def poly_mul(f: Poly, g: Poly) -> Poly:
    out = [0] * (len(f) + len(g) - 1)
    for i, a in enumerate(f):
        for j, b in enumerate(g):
            out[i + j] += a * b
    return out

def twist_factor(p: int, c: int, k: int) -> Poly:
    poly = [0] * (c * k + 1)
    poly[c * k] = p ** k
    return poly

if __name__ == "__main__":
    p = 2
    f = [1, 0, 3]
    params: List[Tuple[int, int]] = [(2, 3), (1, 4), (3, 2)]
    twisted = f
    for c, k in params:
        twisted = poly_mul(twisted, twist_factor(p, c, k))
    lhs = lambda_inv(p, twisted)
    rhs = lambda_inv(p, f) + sum(c * mu_inv(p, twist_factor(p, c, k)) for c, k in params)
    print("lambda(twisted) =", lhs, " lambda(f)+sum c*mu =", rhs)
    assert lhs == rhs
    print("iterated Matsuno twist formula verified")

