function IwasawaPair(p, f):
    c <- gcd of |coefficients of f|          # content
    if c = 0: error 'f must be nonzero'
    mu <- 0; m <- c
    while m mod p = 0: m <- m / p; mu <- mu + 1   # p-adic valuation
    for i from 0 to deg f:
        if (f[i] / c) mod p != 0:
            lambda <- i; break                  # trailing degree of reduction
    return (mu, lambda)

function IwasawaOfProduct(p, [f_1, ..., f_n]):
    total_mu <- 0; total_lambda <- 0
    for each f in [f_1, ..., f_n]:
        (mu, lam) <- IwasawaPair(p, f)
        total_mu <- total_mu + mu
        total_lambda <- total_lambda + lam
    return (total_mu, total_lambda)

