from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List, Tuple

Poly = List[int]

def content(f: Poly) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def padic_val(p: int, n: int) -> int:
    n, v = abs(n), 0
    while n % p == 0:
        n //= p; v += 1
    return v

def iwasawa_pair(p: int, f: Poly) -> Tuple[int, int]:
    c = content(f)
    reduced = [(a // c) % p for a in f]
    return padic_val(p, c), next(i for i, x in enumerate(reduced) if x != 0)

def iwasawa_of_product(p: int, factors: List[Poly]) -> Tuple[int, int]:
    """Compute (mu, lambda) of a finite product WITHOUT expanding the product,
    by summing the invariants of the factors (the homomorphism property)."""
    total_mu, total_lam = 0, 0
    for f in factors:
        mu, lam = iwasawa_pair(p, f)
        total_mu += mu
        total_lam += lam
    return total_mu, total_lam

from __future__ import annotations
from math import gcd
from functools import reduce
from typing import List, Tuple

Poly = List[int]

def content(f: Poly) -> int:
    return reduce(gcd, (abs(c) for c in f), 0)

def padic_val(p: int, n: int) -> int:
    n, v = abs(n), 0
    while n % p == 0:
        n //= p; v += 1
    return v

def mu_inv(p: int, f: Poly) -> int:
    return padic_val(p, content(f))

def lambda_of_iterated_twist(p: int, f: Poly, params: List[Tuple[int, int]]) -> int:
    """lambda of f twisted by the family {p^{k_i} X^{c_i k_i}}, computed via the
    closed-form iterated twist identity: lambda(f) + sum c_i * mu(twist_i)."""
    c0 = content(f)
    reduced = [(a // c0) % p for a in f]
    lam_f = next(i for i, x in enumerate(reduced) if x != 0)
    shift = 0
    for c, k in params:
        # mu of the twist factor p^k X^{ck} equals k
        shift += c * mu_inv(p, [0] * (c * k) + [p ** k])
    return lam_f + shift
